import asyncio
import json
import logging
from typing import Any
from typing import Optional
import urllib.parse

from nat.builder.builder import Builder
from nat.builder.framework_enum import LLMFrameworkEnum
from nat.builder.function_info import FunctionInfo
from nat.cli.register_workflow import register_function
from nat.data_models.component_ref import FunctionRef
from nat.data_models.function import FunctionBaseConfig
from pydantic import BaseModel
from pydantic import Field

logger = logging.getLogger(__name__)


class VSTPictureURLConfig(FunctionBaseConfig, name="vst_picture_url"):
    """Configuration for the VST Picture URL tool."""

    get_replay_picture_url_tool: FunctionRef = Field(
        "vst_get_replay_picture_url",
        description="The name of the MCP tool to call for getting replay picture URLs",
    )
    get_live_picture_url_tool: Optional[FunctionRef] = Field(
        None,
        description="The name of the MCP tool to call for getting live picture URLs (optional)",
    )
    get_sensor_list_tool: FunctionRef = Field(
        "vst_sensor_list",
        description="The name of the MCP tool to call for getting sensor list",
    )
    vst_external_url: str | None = Field(
        None,
        description="The external VST URL for client-facing URLs (replaces base URL in MCP response)",
    )
    expiry_minutes: str | None = Field(
        None,
        description="Optional expiration time in minutes as string containing positive number (default: 10080 - 7 days)",
    )
    overlay_config: bool = Field(
        False,
        description="Whether to enable overlay configuration for object detection overlays",
    )
    max_retries: int = Field(
        3,
        description="The maximum number of retries for getting the picture URL.",
    )
    retry_delay_seconds: int = Field(
        1,
        description="The delay in seconds between retries.",
    )


class VSTPictureURLInput(BaseModel):
    """Input for the VST Picture URL tool"""

    sensor_id: str = Field(
        ...,
        description="The sensor ID to capture image from",
        min_length=1,
    )
    start_time: str | None = Field(
        None,
        description="The start time in ISO 8601 UTC format (e.g., '2025-08-25T03:05:55.752Z'). If not provided, a live picture will be captured.",
    )


class VSTPictureURLOutput(BaseModel):
    """Output for the VST Picture URL tool"""

    image_url: str = Field(
        ...,
        description="Direct URL to access the image file",
    )
    stream_id: str = Field(
        ...,
        description="The stream ID that is mapped from the sensor ID",
    )
    image_metadata: dict[str, Any] = Field(
        ...,
        description="Metadata about the captured image",
    )


@register_function(config_type=VSTPictureURLConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def vst_picture_url(config: VSTPictureURLConfig, builder: Builder):
    """
    VST Picture URL tool that gets replay picture URLs from a specific stream using VST MCP.

    This tool uses the MCP get_replay_picture_url  or get_live_picture_url tool to retrieve temporary URLs
    By default, it uses get_replay_picture_url. It will only use get_live_picture_url if:
    1. start_time is not provided in the input
    2. get_live_picture_url_tool is configured and available

    """

    get_replay_picture_url_tool = await builder.get_tool(
        config.get_replay_picture_url_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN
    )
    if not get_replay_picture_url_tool:
        raise ValueError(
            f"Failed to get MCP tool '{config.get_replay_picture_url_tool}'. Make sure it's configured in your workflow."
        )

    get_live_picture_url_tool = None
    if config.get_live_picture_url_tool:
        get_live_picture_url_tool = await builder.get_tool(
            config.get_live_picture_url_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN
        )
        if not get_live_picture_url_tool:
            logger.warning(
                f"Failed to get MCP tool '{config.get_live_picture_url_tool}'. Live picture functionality will not be available."
            )

    # get the list of sensors
    sensor_list_tool = await builder.get_tool(config.get_sensor_list_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN)
    if not sensor_list_tool:
        raise ValueError(
            f"Failed to get MCP tool '{config.get_sensor_list_tool}'. Make sure it's configured in your workflow."
        )

    async def _vst_picture_url(vst_picture_url_input: VSTPictureURLInput) -> VSTPictureURLOutput:
        """
        Get a picture URL from a specific stream using VST MCP.

        By default uses replay picture tool. Uses live picture only if:
        - start_time is not provided AND live tool is available

        If start_time is not provided, uses replay with current time.

        Args:
            vst_picture_url_input: VSTPictureURLInput containing sensor_id and optional start_time

        Returns:
            VSTPictureURLOutput containing image URL and metadata
        """
        try:
            sensors_str = await sensor_list_tool.ainvoke(input={})
            sensor_id_2_vst_stream_id_map = {}

            if sensors_str:
                # Parse the sensor list response
                text = sensors_str.strip()
                if text and text[0] == text[-1] and text[0] in ('"', "'"):
                    text = text[1:-1]

                sensors_data = json.loads(text)

                # VST returns dictionary where keys are sensor IDs and values are sensor objects
                if isinstance(sensors_data, dict):
                    for sensor_info in sensors_data.values():
                        if isinstance(sensor_info, dict):
                            name = sensor_info.get("name")
                            sensor_id = sensor_info.get("sensorId")
                            if name and sensor_id:
                                sensor_id_2_vst_stream_id_map[name] = sensor_id

                logger.debug(f"sensor_id_2_vst_stream_id_map initialized ==> {sensor_id_2_vst_stream_id_map}")
            else:
                raise ValueError(
                    f"sensor list is empty.  Make sure the sensor {vst_picture_url_input.sensor_id} exist in VST"
                )

            if vst_picture_url_input.sensor_id not in sensor_id_2_vst_stream_id_map:
                available_sensors = list(sensor_id_2_vst_stream_id_map.keys())
                raise ValueError(
                    f"Sensor ID '{vst_picture_url_input.sensor_id}' not found. Available sensors: {available_sensors}"
                )

            stream_id = sensor_id_2_vst_stream_id_map.get(vst_picture_url_input.sensor_id, None)
            if not stream_id:
                raise KeyError(
                    f"stream_id not found for sensor {vst_picture_url_input.sensor_id}.  Existing sensors are: {sensor_id_2_vst_stream_id_map}"
                )

            # Determine whether to use live or replay tool
            # Use live only if: start_time is not provided AND live tool is available
            use_live = vst_picture_url_input.start_time is None and get_live_picture_url_tool is not None

            # Prepare arguments for the MCP tool
            mcp_args = {"stream_id": stream_id}

            if not use_live:
                # Use replay tool
                if vst_picture_url_input.start_time:
                    mcp_args["start_time"] = vst_picture_url_input.start_time
                else:
                    # Use current time for replay when no start_time provided
                    from datetime import datetime
                    from datetime import timezone

                    mcp_args["start_time"] = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
                target_tool = get_replay_picture_url_tool
                picture_type = "replay"
            else:
                # Use live tool
                target_tool = get_live_picture_url_tool
                picture_type = "live"

            if config.overlay_config:
                mcp_args["overlay"] = json.dumps(
                    {"bbox": {"showAll": True}, "color": "green", "thickness": 5, "debug": True, "opacity": 254}
                )

            if config.expiry_minutes:
                mcp_args["expiry_minutes"] = config.expiry_minutes

            mcp_result = None
            last_exception = None
            max_retries = config.max_retries
            retry_delay_seconds = config.retry_delay_seconds

            for attempt in range(max_retries):
                try:
                    logger.info(
                        f"Attempt {attempt + 1}/{max_retries} to get {picture_type} picture URL for sensor {vst_picture_url_input.sensor_id}"
                    )

                    mcp_result_str = await target_tool.ainvoke(mcp_args)

                    logger.debug(f"MCP result being received: {mcp_result_str}")

                    if not mcp_result_str:
                        raise ValueError("Empty result from MCP tool")

                    mcp_result = json.loads(mcp_result_str)

                    if "error" in mcp_result:
                        raise ValueError(f"MCP error: {mcp_result['error']}")

                    # Success!
                    last_exception = None
                    break

                except (ValueError, json.JSONDecodeError, ConnectionError, TimeoutError) as e:
                    last_exception = e
                    logger.warning(f"Attempt {attempt + 1} failed with error: {e}")
                    if attempt < max_retries - 1:
                        await asyncio.sleep(retry_delay_seconds)
                except Exception as e:
                    # Log unexpected exceptions but still retry
                    logger.exception(f"Unexpected error on attempt {attempt + 1}: {type(e).__name__}")
                    last_exception = e
                    if attempt < max_retries - 1:
                        await asyncio.sleep(retry_delay_seconds)

            if last_exception:
                raise last_exception

            image_url = mcp_result.get("imageUrl", "")

            if config.vst_external_url:
                # Replace internal URL with external URL for client access
                image_url = f"{config.vst_external_url}{urllib.parse.urlparse(image_url).path}"

            if not image_url:
                raise ValueError("Missing imageUrl in response")

            # Translate URL: replace INTERNAL_IP with EXTERNAL_IP for cloud deployments

            image_metadata = {
                "absolutePath": mcp_result.get("absolutePath", ""),
                "imageUrl": image_url,
                "expiryISO": mcp_result.get("expiryISO", ""),
                "expiryMinutes": mcp_result.get("expiryMinutes", 10080),
                "type": mcp_result.get("type", picture_type),
            }

            logger.info(f"Successfully retrieved image URL: {image_url}")

            return VSTPictureURLOutput(image_url=image_url, stream_id=stream_id, image_metadata=image_metadata)

        except Exception as e:
            logger.error(f"Error getting VST Picture URL: {e}")
            raise

    yield FunctionInfo.create(
        single_fn=_vst_picture_url,
        description=_vst_picture_url.__doc__,
        input_schema=VSTPictureURLInput,
        single_output_schema=VSTPictureURLOutput,
    )
